// Automatisch erzeugt aus content/ – nicht von Hand bearbeiten.
export const WATER = [{"id":"pazifik","name":"Pazifischer Ozean","aliases":["Pazifik","Stiller Ozean","Großer Ozean","Pacific Ocean","Pacific"],"kind":"Ozean","group":"meer","borders":[],"facts":["Der Pazifik ist größer als alle Landflächen der Erde zusammen und bedeckt rund ein Drittel der Erdoberfläche.","Er liegt zwischen Asien und Australien im Westen und Amerika im Osten; im Marianengraben erreicht er mit knapp 11 000 Metern die tiefste Stelle der Weltmeere.","Ferdinand Magellan nannte ihn ‚Mar Pacífico‘, das friedliche Meer, weil er ihn 1520/21 bei ruhigem Wetter überquerte."]},{"id":"atlantik","name":"Atlantischer Ozean","aliases":["Atlantik","Atlantic Ocean","Atlantic"],"kind":"Ozean","group":"meer","borders":[],"facts":["Der Atlantik trennt Amerika im Westen von Europa und Afrika im Osten und ist der zweitgrößte Ozean der Erde.","Längs durch seine Mitte zieht sich der Mittelatlantische Rücken, ein untermeerisches Gebirge, das auf Island über den Meeresspiegel ragt.","Weil die Kontinente auseinanderdriften, wird der Atlantik jedes Jahr um wenige Zentimeter breiter – etwa so schnell, wie Fingernägel wachsen."]},{"id":"indik","name":"Indischer Ozean","aliases":["Indik","Indian Ocean"],"kind":"Ozean","group":"meer","borders":[],"facts":["Der Indische Ozean liegt zwischen Afrika, Asien und Australien; anders als Atlantik und Pazifik reicht er nicht bis in die Arktis, weil Asien ihn im Norden abschließt.","Als einziger Ozean ist er nach einem Land benannt: nach Indien, das wie ein Keil weit in ihn hineinragt.","Schon vor rund 2000 Jahren nutzten Seefahrer die halbjährlich die Richtung wechselnden Monsunwinde, um ihn zwischen Arabien, Ostafrika und Indien zu überqueren."]},{"id":"arktis","name":"Nordpolarmeer","aliases":["Arktischer Ozean","Nördliches Eismeer","Arctic Ocean"],"kind":"Ozean","group":"meer","borders":[],"facts":["Das Nordpolarmeer ist der kleinste und flachste der Ozeane; ringsum umgeben es Eurasien, Nordamerika und Grönland.","Am Nordpol gibt es kein Land: Er liegt mitten in diesem Ozean auf treibendem Meereis, unter dem das Wasser über 4000 Meter tief ist.","Mit dem Atlantik ist es vor allem über die Framstraße zwischen Grönland und Spitzbergen verbunden, mit dem Pazifik nur über die schmale Beringstraße."]},{"id":"suedpolarmeer","name":"Südpolarmeer","aliases":["Südlicher Ozean","Antarktischer Ozean","Südliches Eismeer","Southern Ocean","Antarctic Ocean"],"kind":"Ozean","group":"meer","borders":[],"facts":["Das Südpolarmeer umschließt die Antarktis; seine Nordgrenze wird meist bei 60 Grad südlicher Breite gezogen.","Als einzige Meeresströmung umkreist der Antarktische Zirkumpolarstrom die ganze Erde – er bewegt über hundertmal so viel Wasser wie alle Flüsse der Welt zusammen.","Viele Fische in seinem bis zu minus zwei Grad kalten Wasser haben körpereigene Frostschutzmittel im Blut, die das Gefrieren verhindern."]},{"id":"mittelmeer","name":"Mittelmeer","aliases":["Mediterranean Sea","Mediterranean","Europäisches Mittelmeer","Mare Nostrum"],"kind":"Meer","group":"meer","borders":["ES","FR","MC","IT","MT","SI","HR","BA","ME","AL","GR","TR","CY","SY","LB","IL","PS","EG","LY","TN","DZ","MA","GB"],"facts":["Das Mittelmeer liegt zwischen Europa, Afrika und Asien; seine einzige natürliche Verbindung zum Ozean ist die rund 14 Kilometer breite Straße von Gibraltar.","Weil mehr Wasser verdunstet, als Flüsse nachliefern, strömt an der Oberfläche ständig Atlantikwasser herein; in der Tiefe fließt salzigeres Wasser hinaus.","Vor rund sechs Millionen Jahren trocknete es fast völlig aus. Vor 5,3 Millionen Jahren brach der Atlantik bei Gibraltar durch und füllte das Becken wieder."]},{"id":"nordsee","name":"Nordsee","aliases":["North Sea"],"kind":"Meer","group":"meer","borders":["GB","NO","DK","DE","NL","BE","FR"],"facts":["Die Nordsee liegt zwischen Großbritannien, Norwegen, Dänemark, Deutschland, den Niederlanden, Belgien und Frankreich; über Skagerrak und Kattegat ist sie mit der Ostsee verbunden.","Das Wattenmeer an den Küsten der Niederlande, Deutschlands und Dänemarks ist das größte zusammenhängende Sand- und Schlickwatt der Erde und UNESCO-Welterbe.","Am Ende der letzten Eiszeit war ihr Süden trockenes Land: Über das heute ‚Doggerland‘ genannte Gebiet konnte man von England zum Festland wandern."]},{"id":"ostsee","name":"Ostsee","aliases":["Baltic Sea","Baltisches Meer","Mare Balticum"],"kind":"Meer","group":"meer","borders":["DE","DK","SE","FI","RU","EE","LV","LT","PL"],"facts":["Neun Staaten grenzen an die Ostsee; mit der Nordsee ist sie über die dänischen Meerengen, Kattegat und Skagerrak sowie den Nord-Ostsee-Kanal verbunden.","Ihr Wasser ist brackig: Viele Flüsse münden ein, aber nur wenig Salzwasser strömt aus der Nordsee nach – im hohen Norden ist es fast süß.","Seit dem Ende der Eiszeit hebt sich das Land im Norden noch immer – Finnland gewinnt dadurch Jahr für Jahr ein Stück Fläche hinzu."]},{"id":"schwarzesmeer","name":"Schwarzes Meer","aliases":["Black Sea"],"kind":"Meer","group":"meer","borders":["TR","BG","RO","UA","RU","GE"],"facts":["Das Schwarze Meer liegt zwischen Südosteuropa und Kleinasien; über Bosporus, Marmarameer und Dardanellen ist es mit dem Mittelmeer verbunden, die Donau mündet hier.","Rund neun Zehntel seines Wassers sind sauerstofffrei. Darum sind in der Tiefe antike Schiffswracks erstaunlich gut erhalten."]},{"id":"asowsches","name":"Asowsches Meer","aliases":["Sea of Azov"],"kind":"Meer","group":"meer","borders":["RU","UA"],"facts":["Das Asowsche Meer ist über die nur rund vier Kilometer breite Straße von Kertsch mit dem Schwarzen Meer verbunden; der Don mündet in seinen Nordosten.","Mit höchstens 14 Metern Tiefe gilt es als flachstes Meer der Welt – im Durchschnitt ist es nur etwa sieben Meter tief."]},{"id":"marmarameer","name":"Marmarameer","aliases":["Marmara-Meer","Sea of Marmara","Propontis"],"kind":"Meer","group":"meer","borders":["TR"],"facts":["Das Marmarameer liegt vollständig in der Türkei und verbindet über Bosporus und Dardanellen das Schwarze Meer mit der Ägäis – zwischen Europa und Asien.","Seinen Namen verdankt es der Insel Marmara, deren Marmor schon in der Antike begehrt war; das griechische Wort ‚marmaron‘ bedeutet Marmor."]},{"id":"adria","name":"Adriatisches Meer","aliases":["Adria","Adriatic Sea","Adriatic"],"kind":"Meer","group":"meer","borders":["IT","SI","HR","BA","ME","AL"],"facts":["Die Adria liegt zwischen Italien und der Balkanhalbinsel; im Süden verbindet sie die Straße von Otranto mit dem Ionischen Meer.","Ihr Name geht auf die antike Hafenstadt Adria im Po-Delta zurück – durch die Ablagerungen des Po liegt der Ort heute rund 22 Kilometer vom Meer entfernt."]},{"id":"aegaeis","name":"Ägäisches Meer","aliases":["Ägäis","Aegean Sea","Aegean"],"kind":"Meer","group":"meer","borders":["GR","TR"],"facts":["Die Ägäis liegt zwischen Griechenland und der Türkei; Kreta schließt sie im Süden ab, die Dardanellen verbinden sie mit dem Marmarameer.","Der Sage nach ist sie nach König Aigeus benannt, der sich ins Meer stürzte, weil er glaubte, sein Sohn Theseus sei vom Minotaurus getötet worden."]},{"id":"tyrrhenisch","name":"Tyrrhenisches Meer","aliases":["Tyrrhenian Sea","Mar Tirreno"],"kind":"Meer","group":"meer","borders":["IT","FR"],"facts":["Das Tyrrhenische Meer liegt zwischen dem italienischen Festland, Sizilien, Sardinien und Korsika; die Straße von Messina verbindet es mit dem Ionischen Meer.","Die Liparische Insel Vulcano in diesem Meer gab allen Vulkanen ihren Namen; sie selbst ist nach Vulcanus benannt, dem römischen Gott des Feuers."]},{"id":"ionisch","name":"Ionisches Meer","aliases":["Ionian Sea","Mar Ionio"],"kind":"Meer","group":"meer","borders":["IT","GR","AL"],"facts":["Das Ionische Meer liegt zwischen Süditalien, Sizilien und Westgriechenland; zu seinen Inseln gehören Korfu, Kefalonia, Ithaka und Zakynthos.","Im Calypsotief südwestlich der griechischen Küste erreicht es über 5200 Meter – die tiefste Stelle des gesamten Mittelmeers."]},{"id":"ligurisch","name":"Ligurisches Meer","aliases":["Ligurian Sea","Mar Ligure"],"kind":"Meer","group":"meer","borders":["IT","FR"],"facts":["Das Ligurische Meer liegt vor der italienischen Riviera zwischen Genua und Korsika; der Golf von Genua bildet seinen nördlichsten Teil.","Italien, Frankreich und Monaco haben hier ein gemeinsames Schutzgebiet für Wale und Delfine eingerichtet, das Pelagos-Schutzgebiet."]},{"id":"balearen","name":"Balearenmeer","aliases":["Balearisches Meer","Balearic Sea","Mar Balear"],"kind":"Meer","group":"meer","borders":["ES"],"facts":["Das Balearenmeer liegt zwischen der spanischen Ostküste um Barcelona und Valencia und den Balearen Mallorca, Menorca, Ibiza und Formentera.","Die ausgedehnten Unterwasserwiesen aus Neptungras zwischen Ibiza und Formentera gehören zum UNESCO-Welterbe."]},{"id":"irischesee","name":"Irische See","aliases":["Irish Sea","Irisches Meer"],"kind":"Meer","group":"meer","borders":["GB","IE"],"facts":["Die Irische See trennt Großbritannien von Irland; in ihrer Mitte liegt die Isle of Man, die nicht zum Vereinigten Königreich gehört, sondern direkt der britischen Krone untersteht.","Im Norden verengt sie sich zum Nordkanal: Zwischen Schottland und Nordirland liegen dort nur 19 Kilometer Wasser."]},{"id":"aermelkanal","name":"Ärmelkanal","aliases":["English Channel","La Manche","Englischer Kanal"],"kind":"Meerenge","group":"meer","borders":["GB","FR"],"facts":["Der deutsche Name übersetzt das französische ‚La Manche‘ – ‚der Ärmel‘, wegen seiner Form; auf Englisch heißt er schlicht ‚English Channel‘.","An der engsten Stelle, der Straße von Dover, trennen England und Frankreich nur rund 33 Kilometer; seit 1994 verbindet sie der Eurotunnel unter dem Meer."]},{"id":"biskaya","name":"Golf von Biskaya","aliases":["Biskaya","Bay of Biscay","Golfe de Gascogne","Golfo de Vizcaya"],"kind":"Golf","group":"meer","borders":["FR","ES"],"facts":["Der Golf von Biskaya liegt zwischen der Westküste Frankreichs und der Nordküste Spaniens; die Loire und die Gironde münden in ihn.","Bei Seeleuten ist er für heftige Stürme und hohen Seegang gefürchtet; in Frankreich heißt er ‚Golfe de Gascogne‘."]},{"id":"nordmeer","name":"Europäisches Nordmeer","aliases":["Nordmeer","Norwegische See","Norwegisches Meer","Norwegian Sea"],"kind":"Meer","group":"meer","borders":["NO","IS","DK"],"facts":["Das Europäische Nordmeer liegt zwischen Norwegen, Island und Spitzbergen; dank warmer Atlantikströmungen bleibt es auch nördlich des Polarkreises eisfrei.","Vor den Lofoten wirbelt der Gezeitenstrom Moskenstraumen – er inspirierte Edgar Allan Poe und Jules Verne zu ihren Geschichten vom ‚Mahlstrom‘."]},{"id":"barentssee","name":"Barentssee","aliases":["Barents Sea","Barentsmeer"],"kind":"Meer","group":"meer","borders":["NO","RU"],"facts":["Die Barentssee liegt nördlich von Norwegen und Russland zwischen Spitzbergen und Nowaja Semlja; ihr Hafen Murmansk friert dank eines Golfstrom-Ausläufers nie zu.","Benannt ist sie nach dem Niederländer Willem Barentsz, der 1596/97 auf Nowaja Semlja überwinterte und auf der Rückfahrt starb."]},{"id":"weissesmeer","name":"Weißes Meer","aliases":["White Sea","Weisses Meer"],"kind":"Meer","group":"meer","borders":["RU"],"facts":["Das Weiße Meer ist fast ganz von russischem Land umschlossen und nur über einen schmalen Meeresarm mit der Barentssee verbunden.","Bevor Peter der Große Sankt Petersburg gründete, war Archangelsk an seiner Küste der wichtigste Seehafen Russlands."]},{"id":"groenlandsee","name":"Grönlandsee","aliases":["Greenland Sea"],"kind":"Meer","group":"meer","borders":["DK","NO","IS"],"facts":["Die Grönlandsee liegt zwischen der Ostküste Grönlands, Spitzbergen, Jan Mayen und Island; im Norden verbindet sie die Framstraße mit dem Nordpolarmeer.","Durch die Framstraße treibt ein Großteil des arktischen Meereises nach Süden; zugleich sinkt hier im Winter stark abgekühltes Oberflächenwasser in große Tiefen."]},{"id":"bottnisch","name":"Bottnischer Meerbusen","aliases":["Bottnischer Golf","Gulf of Bothnia","Pohjanlahti","Bottniska viken"],"kind":"Golf","group":"meer","borders":["SE","FI"],"facts":["Der Bottnische Meerbusen ist der nördlichste Teil der Ostsee zwischen Schweden und Finnland; im Norden ist sein Wasser fast süß und friert dort jeden Winter zu.","An der schwedischen Hohen Küste hat sich das Land seit der Eiszeit um fast 300 Meter gehoben – so stark wie nirgends sonst bekannt; heute UNESCO-Welterbe."]},{"id":"finnisch","name":"Finnischer Meerbusen","aliases":["Finnischer Golf","Gulf of Finland","Suomenlahti","Soome laht"],"kind":"Golf","group":"meer","borders":["FI","RU","EE"],"facts":["Der Finnische Meerbusen reicht zwischen Finnland und Estland bis nach Sankt Petersburg; Helsinki und Tallinn liegen sich nur rund 80 Kilometer gegenüber.","In Sankt Petersburg mündet die Newa – nur 74 Kilometer lang, aber einer der wasserreichsten Flüsse Europas."]},{"id":"kattegat","name":"Kattegat","aliases":["Kattegatt"],"kind":"Meerenge","group":"meer","borders":["DK","SE"],"facts":["Das Kattegat liegt zwischen Jütland und der schwedischen Westküste; im Süden führen Öresund, Großer und Kleiner Belt in die Ostsee.","Der Name kommt aus dem Niederländischen und bedeutet etwa ‚Katzenloch‘: Zwischen Riffen und Sandbänken schien die Durchfahrt so eng, dass kaum eine Katze hindurchpasst."]},{"id":"skagerrak","name":"Skagerrak","aliases":["Skagerak"],"kind":"Meerenge","group":"meer","borders":["NO","SE","DK"],"facts":["Das Skagerrak verbindet die Nordsee mit dem Kattegat und liegt zwischen der Südküste Norwegens, der Westküste Schwedens und der Nordspitze Dänemarks.","An der Landspitze Grenen bei Skagen treffen die Wellen von Skagerrak und Kattegat sichtbar aufeinander – man kann mit je einem Fuß in beiden Meeren stehen."]},{"id":"gibraltar","name":"Straße von Gibraltar","aliases":["Meerenge von Gibraltar","Strait of Gibraltar","Estrecho de Gibraltar","Gibraltar"],"kind":"Meerenge","group":"meer","borders":["ES","MA"],"facts":["Die Straße von Gibraltar trennt Europa von Afrika und verbindet das Mittelmeer mit dem Atlantik; an der engsten Stelle ist sie nur rund 14 Kilometer breit.","Die Felsen an ihren beiden Ufern galten in der Antike als ‚Säulen des Herakles‘ – als Ende der bekannten Welt."]},{"id":"bosporus","name":"Bosporus","aliases":["Bosphorus","Bosporos","İstanbul Boğazı"],"kind":"Meerenge","group":"meer","borders":["TR"],"facts":["Der Bosporus verbindet das Schwarze Meer mit dem Marmarameer und teilt Istanbul in einen europäischen und einen asiatischen Teil.","Die Meerenge ist rund 31 Kilometer lang und an der schmalsten Stelle nur etwa 700 Meter breit; oben fließt Wasser nach Süden, in der Tiefe salzigeres nach Norden."]},{"id":"rotesmeer","name":"Rotes Meer","aliases":["Red Sea"],"kind":"Meer","group":"meer","borders":["EG","SD","ER","DJ","YE","SA","JO","IL"],"facts":["Das Rote Meer trennt Afrika von der Arabischen Halbinsel; im Norden verbindet es der Suezkanal mit dem Mittelmeer, im Süden das Bab al-Mandab mit dem Golf von Aden.","Kein nennenswerter Fluss mündet in das Rote Meer, und es verdunstet viel Wasser – deshalb gehört es zu den salzigsten Meeren der Welt."]},{"id":"persischergolf","name":"Persischer Golf","aliases":["Arabischer Golf","Persian Gulf","Arabian Gulf"],"kind":"Golf","group":"meer","borders":["IR","IQ","KW","SA","BH","QA","AE","OM"],"facts":["Der Persische Golf liegt zwischen Iran und der Arabischen Halbinsel; nur die Straße von Hormus verbindet ihn mit dem offenen Meer, im Norden münden Euphrat und Tigris als Schatt al-Arab.","Bevor Öl gefunden wurde, lebten viele Anrainer vom Perlentauchen; in Bahrain erinnert ein UNESCO-Welterbe an diese Tradition."]},{"id":"golfvonoman","name":"Golf von Oman","aliases":["Gulf of Oman"],"kind":"Golf","group":"meer","borders":["OM","AE","IR","PK"],"facts":["Der Golf von Oman verbindet das Arabische Meer über die Straße von Hormus mit dem Persischen Golf; Anrainer sind Oman, die Emirate, Iran und Pakistan.","Omans Hauptstadt Maskat liegt an seiner Küste. Über den Hafen Fudschaira können die Emirate Öl verschiffen, ohne die Straße von Hormus zu passieren."]},{"id":"golfvonaden","name":"Golf von Aden","aliases":["Gulf of Aden"],"kind":"Golf","group":"meer","borders":["YE","DJ","SO"],"facts":["Der Golf von Aden liegt zwischen Jemen und dem Horn von Afrika; über das Bab al-Mandab ist er mit dem Roten Meer verbunden.","Benannt ist er nach der jemenitischen Hafenstadt Aden. Durch ihn führt der kürzeste Seeweg zwischen Europa und Asien, der über den Suezkanal."]},{"id":"arabischesmeer","name":"Arabisches Meer","aliases":["Arabische See","Arabian Sea"],"kind":"Meer","group":"meer","borders":["IN","PK","OM","YE","SO"],"facts":["Das Arabische Meer liegt zwischen der Arabischen Halbinsel und Indien; der Indus mündet hier, und an seinen Küsten liegen Karatschi und Mumbai.","Über dem Arabischen Meer nimmt der Südwestmonsun die Feuchtigkeit auf, die ab etwa Juni als Monsunregen auf Indiens Westküste niedergeht."]},{"id":"lakkadiven","name":"Lakkadivensee","aliases":["Lakkadivenmeer","Laccadive Sea","Lakshadweep Sea"],"kind":"Meer","group":"meer","borders":["IN","LK","MV"],"facts":["Die Lakkadivensee liegt zwischen der Südwestküste Indiens, Sri Lanka und den Malediven; im Nordosten begrenzt sie die Adamsbrücke, eine Kette aus Sandbänken.","Benannt ist sie nach den indischen Lakkadiven. Deren heutiger Name Lakshadweep bedeutet ‚hunderttausend Inseln‘ – tatsächlich sind es nur 36."]},{"id":"bengalen","name":"Golf von Bengalen","aliases":["Bengalischer Golf","Bay of Bengal"],"kind":"Golf","group":"meer","borders":["IN","BD","MM","LK"],"facts":["Der Golf von Bengalen liegt zwischen Indien, Sri Lanka, Bangladesch und Myanmar; im Osten begrenzen ihn die Andamanen und Nikobaren.","An seiner Nordküste bilden Ganges und Brahmaputra ein riesiges Delta mit den Sundarbans, dem größten Mangrovenwald der Erde."]},{"id":"andamanensee","name":"Andamanensee","aliases":["Andamanisches Meer","Andaman Sea"],"kind":"Meer","group":"meer","borders":["MM","TH","IN","ID"],"facts":["Die Andamanensee liegt östlich der indischen Andamanen und Nikobaren vor den Küsten Myanmars und Thailands; im Süden geht sie in die Straße von Malakka über.","In der Bucht von Phang Nga ragen steile Kalkfelsen aus dem Wasser – einer wurde durch einen James-Bond-Film von 1974 als ‚James Bond Island‘ berühmt."]},{"id":"malakka","name":"Straße von Malakka","aliases":["Malakkastraße","Strait of Malacca","Selat Melaka"],"kind":"Meerenge","group":"meer","borders":["MY","ID","TH"],"facts":["Die Straße von Malakka trennt die Malaiische Halbinsel von Sumatra und verbindet den Indischen Ozean mit dem Südchinesischen Meer.","Sie ist einer der meistbefahrenen Schifffahrtswege der Welt und nach der alten Handelsstadt Malakka benannt, deren Altstadt UNESCO-Welterbe ist."]},{"id":"suedchinesisch","name":"Südchinesisches Meer","aliases":["Südchinesische See","South China Sea"],"kind":"Meer","group":"meer","borders":["CN","TW","PH","MY","BN","ID","VN"],"facts":["Das Südchinesische Meer liegt zwischen Südchina, Vietnam, den Philippinen und Borneo; im Norden verbindet es die Taiwanstraße mit dem Ostchinesischen Meer.","Hongkong und Macau liegen an der Mündung des Perlflusses in dieses Meer, und auch der Mekong mündet hier mit einem großen Delta."]},{"id":"ostchinesisch","name":"Ostchinesisches Meer","aliases":["Ostchinesische See","East China Sea"],"kind":"Meer","group":"meer","borders":["CN","TW","JP","KR"],"facts":["Das Ostchinesische Meer liegt zwischen China, Taiwan, Südkorea und Japan; die Kette der Ryūkyū-Inseln mit Okinawa trennt es vom offenen Pazifik.","Bei Shanghai mündet der Jangtsekiang hinein, mit rund 6300 Kilometern der längste Fluss Asiens."]},{"id":"gelbesmeer","name":"Gelbes Meer","aliases":["Yellow Sea","Huang Hai"],"kind":"Meer","group":"meer","borders":["CN","KP","KR"],"facts":["Das Gelbe Meer liegt zwischen China und der Koreanischen Halbinsel; seinen Namen hat es vom gelblichen Schlamm, den große Flüsse wie der Huang He hineintragen.","An der Westküste Koreas steigt und fällt das Wasser mit den Gezeiten oft um vier bis acht Meter – bei Ebbe fallen dort weite Wattflächen trocken."]},{"id":"japanischesmeer","name":"Japanisches Meer","aliases":["Sea of Japan","Ostmeer","East Sea"],"kind":"Meer","group":"meer","borders":["JP","KR","KP","RU"],"facts":["Das Japanische Meer liegt zwischen Japan, Korea und dem Fernen Osten Russlands; an seiner Küste endet in Wladiwostok die Transsibirische Eisenbahn.","Kalte Winterluft aus Sibirien nimmt über dem Meer Feuchtigkeit auf und lädt sie an Japans Westküste als Schnee ab – dort liegen einige der schneereichsten Städte der Welt."]},{"id":"ochotskisch","name":"Ochotskisches Meer","aliases":["Sea of Okhotsk"],"kind":"Meer","group":"meer","borders":["RU","JP"],"facts":["Das Ochotskische Meer wird von der Halbinsel Kamtschatka, den Kurilen, Sachalin und der japanischen Insel Hokkaido umrahmt.","Im Winter ist es großteils zugefroren; Treibeis erreicht dann sogar die Nordküste Hokkaidos."]},{"id":"beringmeer","name":"Beringmeer","aliases":["Beringsee","Bering Sea"],"kind":"Meer","group":"meer","borders":["US","RU"],"facts":["Das Beringmeer liegt zwischen Alaska und Sibirien; im Süden begrenzt es der Bogen der Aleuten, im Norden führt die Beringstraße ins Nordpolarmeer.","In den Eiszeiten lag sein nördlicher Teil trocken: Über diese Landbrücke Beringia gelangten die ersten Menschen von Asien nach Amerika."]},{"id":"philippinensee","name":"Philippinensee","aliases":["Philippinisches Meer","Philippine Sea"],"kind":"Meer","group":"meer","borders":["PH","TW","JP","PW","US"],"facts":["Die Philippinensee liegt östlich der Philippinen und Taiwans, südlich von Japan und westlich der Marianen.","An ihrem Westrand erreicht der Philippinengraben rund 10 500 Meter Tiefe – eine der tiefsten Stellen der Weltmeere."]},{"id":"javasee","name":"Javasee","aliases":["Javameer","Java Sea","Laut Jawa"],"kind":"Meer","group":"meer","borders":["ID"],"facts":["Die Javasee liegt zwischen Java, Borneo und Sumatra; an ihrer Küste liegt die indonesische Millionenstadt Jakarta.","Sie ist im Schnitt nur rund 45 Meter tief. In der Eiszeit lag sie trocken und verband Java, Sumatra und Borneo mit dem asiatischen Festland."]},{"id":"celebessee","name":"Celebessee","aliases":["Sulawesisee","Celebes Sea","Laut Sulawesi"],"kind":"Meer","group":"meer","borders":["ID","PH","MY"],"facts":["Die Celebessee liegt zwischen der philippinischen Insel Mindanao, Borneo und Sulawesi – Celebes ist der alte Name dieser indonesischen Insel.","Vor Manado im Norden Sulawesis wurde 1998 ein Quastenflosser gefangen – er gehörte zu einer zweiten, bis dahin unbekannten Art dieses urtümlichen Fisches."]},{"id":"sulusee","name":"Sulusee","aliases":["Sulu Sea"],"kind":"Meer","group":"meer","borders":["PH","MY"],"facts":["Die Sulusee liegt zwischen Palawan, Mindanao und dem Norden Borneos; die Inselkette des Sulu-Archipels trennt sie von der Celebessee.","In ihrer Mitte liegt das Tubbataha-Riff, ein abgelegenes Korallenriff, das seit 1993 zum UNESCO-Welterbe gehört."]},{"id":"bandasee","name":"Bandasee","aliases":["Banda Sea","Laut Banda"],"kind":"Meer","group":"meer","borders":["ID","TL"],"facts":["Die Bandasee liegt im Osten Indonesiens zwischen Sulawesi, den Molukken und Timor. Ihre Banda-Inseln waren lange die einzige Quelle für Muskatnuss.","Im Frieden von Breda 1667 behielten die Engländer Manhattan; im Gegenzug überließen sie den Niederländern die kleine Muskatinsel Run in der Bandasee."]},{"id":"golfvonthailand","name":"Golf von Thailand","aliases":["Golf von Siam","Gulf of Thailand","Gulf of Siam"],"kind":"Golf","group":"meer","borders":["TH","KH","VN","MY"],"facts":["Der Golf von Thailand liegt zwischen der Malaiischen Halbinsel und Indochina; an seiner Nordspitze mündet der Chao Phraya, an dem Bangkok liegt.","Früher hieß er Golf von Siam – nach dem alten Namen Thailands. Ferieninseln wie Ko Samui liegen in ihm."]},{"id":"tonkin","name":"Golf von Tonkin","aliases":["Tonkin-Golf","Tonkingolf","Gulf of Tonkin","Beibu-Golf"],"kind":"Golf","group":"meer","borders":["VN","CN"],"facts":["Der Golf von Tonkin liegt zwischen Nordvietnam und der chinesischen Insel Hainan; Tonkin war der französische Kolonialname für Nordvietnam.","An seiner Küste liegt die Halong-Bucht mit weit über 1000 steilen Kalksteininseln – seit 1994 UNESCO-Welterbe."]},{"id":"karasee","name":"Karasee","aliases":["Kara Sea","Karisches Meer"],"kind":"Meer","group":"meer","borders":["RU"],"facts":["Die Karasee liegt vor der Nordküste Sibiriens zwischen der Doppelinsel Nowaja Semlja und der Taimyrhalbinsel.","Mit Ob und Jenissei münden zwei der größten Ströme Sibiriens in sie – deshalb ist ihr Wasser nahe der Küste nur schwach salzig."]},{"id":"laptewsee","name":"Laptewsee","aliases":["Laptev Sea","Laptevsee"],"kind":"Meer","group":"meer","borders":["RU"],"facts":["Die Laptewsee liegt vor Nordsibirien zwischen der Taimyrhalbinsel und den Neusibirischen Inseln; die Lena mündet hier mit einem der größten Flussdeltas der Erde.","Benannt ist sie nach den Cousins Dmitri und Chariton Laptew, russischen Marineoffizieren, die im 18. Jahrhundert die sibirische Küste kartierten."]},{"id":"ostsibirisch","name":"Ostsibirische See","aliases":["Ostsibirisches Meer","East Siberian Sea"],"kind":"Meer","group":"meer","borders":["RU"],"facts":["Die Ostsibirische See liegt vor Nordostsibirien zwischen den Neusibirischen Inseln und der Wrangelinsel; die Kolyma mündet hier.","Im Dauerfrostboden der Neusibirischen Inseln an ihrem Westrand stecken so viele Mammutknochen, dass dort seit dem 18. Jahrhundert Elfenbein gesammelt wird."]},{"id":"tschuktschensee","name":"Tschuktschensee","aliases":["Tschuktschenmeer","Chukchi Sea"],"kind":"Meer","group":"meer","borders":["RU","US"],"facts":["Die Tschuktschensee liegt nördlich der Beringstraße zwischen der russischen Tschuktschen-Halbinsel und Alaska; benannt ist sie nach dem Volk der Tschuktschen.","Auf der Wrangelinsel an ihrem Westrand überlebten Mammuts bis vor rund 4000 Jahren – als in Ägypten längst Pyramiden standen."]},{"id":"golfvonguinea","name":"Golf von Guinea","aliases":["Gulf of Guinea"],"kind":"Golf","group":"meer","borders":["CI","GH","TG","BJ","NG","CM","GQ","ST","GA"],"facts":["Der Golf von Guinea ist die große Bucht an der Westküste Afrikas zwischen der Elfenbeinküste und Gabun; der Niger mündet hier mit einem riesigen Delta.","Rund 600 Kilometer südlich der Küste Ghanas kreuzen sich Äquator und Nullmeridian – der Punkt 0°/0° wird oft dem Golf von Guinea zugerechnet."]},{"id":"mosambik","name":"Straße von Mosambik","aliases":["Kanal von Mosambik","Mosambikstraße","Mozambique Channel"],"kind":"Meerenge","group":"meer","borders":["MZ","MG","KM"],"facts":["Die Straße von Mosambik trennt Madagaskar vom afrikanischen Festland; an der schmalsten Stelle ist sie rund 420 Kilometer breit.","Bei den Komoren an ihrem Nordende leben Quastenflosser – Fische, die man bis 1938 für seit Millionen Jahren ausgestorben hielt."]},{"id":"karibik","name":"Karibisches Meer","aliases":["Karibik","Karibische See","Caribbean Sea","Mar Caribe","Antillenmeer"],"kind":"Meer","group":"meer","borders":["MX","BZ","GT","HN","NI","CR","PA","CO","VE","CU","JM","HT","DO","AG","KN","DM","LC","VC","GD","TT","US","GB","FR","NL"],"facts":["Das Karibische Meer liegt zwischen Mittelamerika, dem Norden Südamerikas und den Großen und Kleinen Antillen; der Panamakanal verbindet es mit dem Pazifik.","Benannt ist es nach den Kariben, einem indigenen Volk der Kleinen Antillen. Im Kaimangraben ist es fast 7700 Meter tief."]},{"id":"golfvonmexiko","name":"Golf von Mexiko","aliases":["Mexikanischer Golf","Gulf of Mexico","Golfo de México","Gulf of America"],"kind":"Golf","group":"meer","borders":["US","MX","CU"],"facts":["Der Golf von Mexiko wird von den USA, Mexiko und Kuba umschlossen; der Mississippi mündet in ihn, und der Golfstrom ist nach ihm benannt.","Vor rund 66 Millionen Jahren schlug hier der Asteroid ein, der zum Aussterben der Dinosaurier beitrug; der Chicxulub-Krater liegt teils unter dem Golf."]},{"id":"hudsonbay","name":"Hudson Bay","aliases":["Hudsonbai","Hudsonbucht","Hudson-Bucht","Baie d’Hudson"],"kind":"Bucht","group":"meer","borders":["CA"],"facts":["Die Hudson Bay ist ein riesiges Binnenmeer im Nordosten Kanadas; benannt ist sie nach Henry Hudson, den seine meuternde Mannschaft dort 1611 in einem Boot aussetzte.","In Churchill an ihrem Westufer warten jeden Herbst Eisbären darauf, dass die Bucht zufriert – der Ort nennt sich ‚Welthauptstadt der Eisbären‘."]},{"id":"baffinbay","name":"Baffin Bay","aliases":["Baffinbai","Baffin-Bucht","Baffinbucht"],"kind":"Bucht","group":"meer","borders":["CA","DK"],"facts":["Die Baffin Bay liegt zwischen der kanadischen Baffininsel und Grönland; benannt ist sie nach dem Engländer William Baffin, der sie 1616 befuhr.","Aus dem Eisfjord von Ilulissat an ihrer grönländischen Küste, einem UNESCO-Welterbe, treiben riesige Eisberge in die Bucht."]},{"id":"labradorsee","name":"Labradorsee","aliases":["Labrador Sea","Labradormeer"],"kind":"Meer","group":"meer","borders":["CA","DK"],"facts":["Die Labradorsee liegt zwischen der kanadischen Halbinsel Labrador und Südgrönland; der kalte Labradorstrom trägt von hier Eisberge bis vor Neufundland.","Um das Jahr 1000 überquerten Wikinger von Grönland aus die Labradorsee und landeten in Nordamerika – rund 500 Jahre vor Kolumbus."]},{"id":"beaufortsee","name":"Beaufortsee","aliases":["Beaufort Sea","Beaufortmeer"],"kind":"Meer","group":"meer","borders":["US","CA"],"facts":["Die Beaufortsee liegt vor der Nordküste Alaskas und Kanadas; hier mündet der Mackenzie, Kanadas längster Fluss.","Benannt ist sie nach dem britischen Admiral Francis Beaufort – dem Namensgeber der Beaufortskala für Windstärken."]},{"id":"golfvonalaska","name":"Golf von Alaska","aliases":["Alaskagolf","Gulf of Alaska"],"kind":"Golf","group":"meer","borders":["US"],"facts":["Der Golf von Alaska ist die weite Bucht an der Südküste Alaskas zwischen der Alaska-Halbinsel und dem Alexanderarchipel.","Auf der Insel Kodiak im Golf leben die Kodiakbären – sie gehören neben Eisbären zu den größten Landraubtieren der Erde."]},{"id":"golfvonkalifornien","name":"Golf von Kalifornien","aliases":["Kalifornischer Golf","Gulf of California","Golfo de California","Sea of Cortez","Mar de Cortés"],"kind":"Golf","group":"meer","borders":["MX"],"facts":["Der Golf von Kalifornien trennt die Halbinsel Niederkalifornien vom mexikanischen Festland; der Colorado River, dessen Mündung hier liegt, erreicht das Meer heute meist nicht mehr.","Seine Inseln und Schutzgebiete gehören seit 2005 zum UNESCO-Welterbe; er gilt als eines der artenreichsten Meere der Erde."]},{"id":"sargassosee","name":"Sargassosee","aliases":["Sargassomeer","Sargasso Sea"],"kind":"Meer","group":"meer","borders":["GB"],"facts":["Als einziges Meer grenzt die Sargassosee an kein Festland: Sie liegt mitten im Nordatlantik und wird nur von Meeresströmungen begrenzt; an ihrem Westrand liegen die britischen Bermudas.","Nach heutigem Wissen laichen hier die Aale aus Europa und Nordamerika; ihre Larven treiben danach mit dem Golfstrom Tausende Kilometer weit zu den Küsten."]},{"id":"lorenzgolf","name":"Sankt-Lorenz-Golf","aliases":["St.-Lorenz-Golf","Golf von St. Lorenz","Lorenzgolf","Gulf of Saint Lawrence","Gulf of St. Lawrence","Golfe du Saint-Laurent"],"kind":"Golf","group":"meer","borders":["CA"],"facts":["Der Sankt-Lorenz-Golf liegt zwischen Québec, den kanadischen Seeprovinzen und Neufundland; über ihn fließt das Wasser der Großen Seen mit dem Sankt-Lorenz-Strom in den Atlantik.","Die 12,9 Kilometer lange Confederation Bridge verbindet die Prinz-Edward-Insel mit dem Festland – die längste Brücke der Welt über zeitweise zugefrorenem Meer."]},{"id":"rioplata","name":"Río de la Plata","aliases":["Rio de la Plata","La-Plata-Strom","La Plata","River Plate"],"kind":"Mündungstrichter","group":"meer","borders":["AR","UY"],"facts":["Paraná und Uruguay bilden gemeinsam den Río de la Plata; an seinen Ufern liegen sich die Hauptstädte Buenos Aires und Montevideo gegenüber.","Mit bis zu 220 Kilometern Breite gilt er als breiteste Flussmündung der Welt. Sein Name bedeutet ‚Silberfluss‘ – nach Silberschätzen, die man hier vermutete."]},{"id":"drakestrasse","name":"Drakestraße","aliases":["Drake-Passage","Drakepassage","Drake Passage","Mar de Hoces"],"kind":"Meerenge","group":"meer","borders":["CL"],"facts":["Die Drakestraße trennt die Südspitze Südamerikas am Kap Hoorn von der Antarktischen Halbinsel und verbindet Atlantik und Pazifik; sie ist rund 800 Kilometer breit.","Weil die Westwinde hier ungebremst um die Erde fegen, gilt sie als eines der stürmischsten Seegebiete. Benannt ist sie nach dem Seefahrer Francis Drake."]},{"id":"magellan","name":"Magellanstraße","aliases":["Straße von Magellan","Strait of Magellan","Estrecho de Magallanes"],"kind":"Meerenge","group":"meer","borders":["CL"],"facts":["Die Magellanstraße trennt das südamerikanische Festland von Feuerland; an ihrem Ufer liegt Punta Arenas, eine der südlichsten Städte der Welt.","Ferdinand Magellan durchfuhr sie 1520 als erster Europäer. Die rund 570 Kilometer lange Wasserstraße ist an der engsten Stelle nur etwa zwei Kilometer breit."]},{"id":"korallenmeer","name":"Korallenmeer","aliases":["Korallensee","Coral Sea"],"kind":"Meer","group":"meer","borders":["AU","PG","SB","VU","FR"],"facts":["Das Korallenmeer liegt vor der Nordostküste Australiens und wird von Neuguinea, den Salomonen, Vanuatu und Neukaledonien begrenzt.","An seinem Westrand erstreckt sich über mehr als 2000 Kilometer das Great Barrier Reef, das größte Korallenriffsystem der Erde."]},{"id":"tasmansee","name":"Tasmansee","aliases":["Tasmanische See","Tasman Sea"],"kind":"Meer","group":"meer","borders":["AU","NZ"],"facts":["Die Tasmansee trennt Australien von Neuseeland; Australier und Neuseeländer nennen sie scherzhaft ‚The Ditch‘ – den Graben.","Benannt ist sie nach dem Niederländer Abel Tasman, der 1642 als erster Europäer Tasmanien und Neuseeland erreichte."]},{"id":"arafurasee","name":"Arafurasee","aliases":["Arafurameer","Arafura Sea"],"kind":"Meer","group":"meer","borders":["AU","ID"],"facts":["Die Arafurasee liegt zwischen Nordaustralien und Neuguinea; im Osten schließt die Torresstraße an, im Süden öffnet sich der Golf von Carpentaria.","Sie ist meist nur 50 bis 80 Meter tief. In der Eiszeit lag sie trocken, sodass Australien und Neuguinea eine zusammenhängende Landmasse bildeten."]},{"id":"timorsee","name":"Timorsee","aliases":["Timormeer","Timor Sea"],"kind":"Meer","group":"meer","borders":["AU","TL","ID"],"facts":["Die Timorsee liegt zwischen der Insel Timor und Nordaustralien; die australische Stadt Darwin liegt an ihrem Rand.","Timor kommt vom malaiischen Wort ‚timur‘ für Osten. Der Staatsname Timor-Leste – ‚leste‘ ist Portugiesisch für Osten – heißt also doppelt ‚Ost‘."]},{"id":"salomonensee","name":"Salomonensee","aliases":["Salomonsee","Solomon Sea"],"kind":"Meer","group":"meer","borders":["PG","SB"],"facts":["Die Salomonensee liegt zwischen der Osthälfte Neuguineas, der Insel Neubritannien und den Salomonen; im Neubritannien-Graben ist sie über 9000 Meter tief.","Die Salomonen erhielten ihren Namen nach der Reise des Spaniers Álvaro de Mendaña 1568: Man vermutete dort die sagenhaften Goldschätze König Salomons."]},{"id":"bismarcksee","name":"Bismarcksee","aliases":["Bismarckmeer","Bismarck Sea"],"kind":"Meer","group":"meer","borders":["PG"],"facts":["Die Bismarcksee liegt nördlich von Neuguinea und wird vom Bismarck-Archipel mit Neubritannien und Neuirland umschlossen.","Ihr Name erinnert an Otto von Bismarck und die Kolonialzeit: Bis 1914 gehörten Nordost-Neuguinea und die Inseln ringsum als Deutsch-Neuguinea zum Deutschen Reich."]},{"id":"carpentaria","name":"Golf von Carpentaria","aliases":["Carpentariagolf","Gulf of Carpentaria"],"kind":"Golf","group":"meer","borders":["AU"],"facts":["Der Golf von Carpentaria ist eine große, flache Bucht im Norden Australiens zwischen Arnhemland und der Kap-York-Halbinsel.","Von September bis November ziehen über seinem Süden oft die ‚Morning Glory‘-Wolken auf – röhrenförmige Wolkenwalzen, bis zu 1000 Kilometer lang."]},{"id":"australbucht","name":"Große Australische Bucht","aliases":["Australische Bucht","Great Australian Bight"],"kind":"Bucht","group":"meer","borders":["AU"],"facts":["Die Große Australische Bucht ist der weite Bogen der australischen Südküste; hier bricht die baumlose Nullarbor-Ebene an den bis zu 120 Meter hohen Bunda-Klippen ab.","Jeden Winter kommen Südkaper an den Kopf der Bucht, um dort ihre Kälber zur Welt zu bringen."]},{"id":"bassstrasse","name":"Bass-Straße","aliases":["Bassstraße","Bass Strait"],"kind":"Meerenge","group":"meer","borders":["AU"],"facts":["Die rund 250 Kilometer breite Bass-Straße trennt Tasmanien vom australischen Festland; in der letzten Eiszeit lag sie trocken.","Benannt ist sie nach George Bass, der 1798/99 mit Matthew Flinders Tasmanien umsegelte und so bewies, dass es eine Insel ist."]},{"id":"weddellmeer","name":"Weddellmeer","aliases":["Weddellsee","Weddell Sea"],"kind":"Meer","group":"meer","borders":[],"facts":["Das Weddellmeer liegt östlich der Antarktischen Halbinsel. 1915 zerdrückte sein Packeis Shackletons Schiff ‚Endurance‘; das Wrack wurde 2022 in gut 3000 Metern Tiefe gefunden.","1986 maßen Forscher hier eine Sichttiefe von rund 80 Metern – das Wasser war so klar wie destilliertes Wasser."]},{"id":"rossmeer","name":"Rossmeer","aliases":["Rosssee","Ross Sea"],"kind":"Meer","group":"meer","borders":[],"facts":["Das Rossmeer ist eine tiefe Bucht der Antarktis südlich von Neuseeland; im Süden bedeckt es das Ross-Schelfeis, das größte Schelfeis der Erde – etwa so groß wie Frankreich.","Benannt ist es nach James Clark Ross, der es 1841 entdeckte. An seinem Rand erhebt sich der Mount Erebus, der südlichste aktive Vulkan der Erde."]},{"id":"kaspisches","name":"Kaspisches Meer","aliases":["Kaspisee","Kaspische See","Kaspi","Caspian Sea"],"kind":"See","group":"see","borders":["RU","KZ","TM","IR","AZ"],"facts":["Das Kaspische Meer ist der größte See der Erde – etwa so groß wie Deutschland. Meer heißt es wegen seiner Größe und seines leicht salzigen Wassers.","Es liegt zwischen Europa und Asien; Anrainer sind Russland, Kasachstan, Turkmenistan, Iran und Aserbaidschan.","Die Wolga liefert rund vier Fünftel seines Zuflusses; einen Abfluss zum Ozean hat es nicht, und sein Spiegel liegt unter dem Meeresniveau."]},{"id":"baikal","name":"Baikalsee","aliases":["Baikal","Bajkal","Lake Baikal","Ozero Baykal"],"kind":"See","group":"see","borders":["RU"],"facts":["Mit gut 1600 Metern ist der Baikalsee der tiefste See der Erde, mit 25 bis 30 Millionen Jahren auch der älteste.","Er enthält mehr Wasser als alle fünf Großen Seen Nordamerikas zusammen – über ein Fünftel des Süßwassers an der Erdoberfläche.","Der sichelförmige See liegt in Südsibirien nahe der Grenze zur Mongolei; über 300 Flüsse münden in ihn, nur die Angara fließt ab."]},{"id":"victoria","name":"Victoriasee","aliases":["Viktoriasee","Lake Victoria","Nalubaale","Ukerewe"],"kind":"See","group":"see","borders":["UG","KE","TZ"],"facts":["Der Victoriasee ist der größte See Afrikas und nach dem Oberen See in Nordamerika der zweitgrößte Süßwassersee der Erde.","Uganda, Kenia und Tansania teilen sich den See; benannt hat ihn der britische Entdecker John Hanning Speke 1858 nach Königin Victoria.","Bei Jinja in Uganda verlässt der Weiße Nil den See – er gilt deshalb als Hauptquelle des Nils."]},{"id":"tanganjika","name":"Tanganjikasee","aliases":["Tanganyikasee","Tanganjika","Lake Tanganyika"],"kind":"See","group":"see","borders":["TZ","CD","BI","ZM"],"facts":["Der Tanganjikasee ist mit rund 670 Kilometern der längste Süßwassersee der Erde; Tansania, die Demokratische Republik Kongo, Burundi und Sambia teilen sich seine Ufer.","In Ujiji an seinem Ostufer fand der Reporter Henry Morton Stanley 1871 den verschollen geglaubten Forscher David Livingstone."]},{"id":"malawisee","name":"Malawisee","aliases":["Njassasee","Nyasasee","Lake Malawi","Lake Nyasa","Lago Niassa"],"kind":"See","group":"see","borders":["MW","MZ","TZ"],"facts":["Der Malawisee liegt im Süden des Ostafrikanischen Grabens zwischen Malawi, Mosambik und Tansania; er ist der drittgrößte See Afrikas.","Kein See der Erde beherbergt mehr Fischarten: Hunderte Arten von Buntbarschen leben nur hier."]},{"id":"oberersee","name":"Oberer See","aliases":["Lake Superior","Lac Supérieur"],"kind":"See","group":"see","borders":["CA","US"],"facts":["Der Obere See ist der westlichste der Großen Seen an der Grenze zwischen Kanada und den USA – und flächenmäßig der größte Süßwassersee der Erde.","Er fasst mehr Wasser als die übrigen vier Großen Seen zusammen; es würde ganz Nord- und Südamerika rund 30 Zentimeter hoch bedecken."]},{"id":"michigansee","name":"Michigansee","aliases":["Michigan-See","Lake Michigan"],"kind":"See","group":"see","borders":["US"],"facts":["Der Michigansee ist der einzige der fünf Großen Seen, der vollständig in den USA liegt; an seinem Südwestufer liegt Chicago.","Genau genommen bilden er und der Huronsee einen einzigen See: Beide sind über die breite Straße von Mackinac verbunden und haben denselben Wasserspiegel."]},{"id":"huronsee","name":"Huronsee","aliases":["Huron-See","Lake Huron"],"kind":"See","group":"see","borders":["CA","US"],"facts":["Der Huronsee liegt zwischen der kanadischen Provinz Ontario und dem US-Bundesstaat Michigan; benannt ist er nach dem Volk der Huronen.","In ihm liegt Manitoulin, die größte Insel der Welt in einem Binnensee – mit eigenen Seen darauf."]},{"id":"eriesee","name":"Eriesee","aliases":["Erie-See","Lake Erie"],"kind":"See","group":"see","borders":["CA","US"],"facts":["Der Eriesee liegt zwischen Ontario und den USA; sein Wasser fließt über den Niagara und die Niagarafälle in den Ontariosee.","Mit im Schnitt nur etwa 19 Metern Tiefe ist er der flachste der Großen Seen – er erwärmt sich im Sommer am schnellsten und friert im Winter am häufigsten zu."]},{"id":"ontariosee","name":"Ontariosee","aliases":["Ontario-See","Lake Ontario"],"kind":"See","group":"see","borders":["CA","US"],"facts":["Der Ontariosee ist der kleinste und östlichste der Großen Seen; über den Sankt-Lorenz-Strom fließt sein Wasser in den Atlantik.","An seinem Nordwestufer liegt Toronto; die kanadische Provinz Ontario ist nach dem See benannt."]},{"id":"baerensee","name":"Großer Bärensee","aliases":["Bärensee","Great Bear Lake","Sahtú"],"kind":"See","group":"see","borders":["CA"],"facts":["Der Große Bärensee in Kanadas Nordwest-Territorien ist der größte See, der ganz in Kanada liegt; der nördliche Polarkreis verläuft durch ihn.","Er ist von Ende November bis in den Juli hinein zugefroren – mehr als die Hälfte des Jahres."]},{"id":"sklavensee","name":"Großer Sklavensee","aliases":["Sklavensee","Great Slave Lake"],"kind":"See","group":"see","borders":["CA"],"facts":["Der Große Sklavensee liegt in Kanadas Nordwest-Territorien; an seinem Nordufer liegt deren Hauptstadt Yellowknife.","Mit gut 600 Metern ist er der tiefste See Nordamerikas. Sein Name geht auf die Slavey zurück, ein indigenes Volk der Dene."]},{"id":"winnipegsee","name":"Winnipegsee","aliases":["Winnipeg-See","Lake Winnipeg"],"kind":"See","group":"see","borders":["CA"],"facts":["Der Winnipegsee liegt in der kanadischen Provinz Manitoba nördlich der Stadt Winnipeg; sein Name kommt aus der Sprache der Cree und bedeutet ‚trübes Wasser‘.","Er ist ein Überrest des eiszeitlichen Agassizsees, der einst größer war als alle heutigen Großen Seen zusammen."]},{"id":"salzsee","name":"Großer Salzsee","aliases":["Salzsee","Great Salt Lake"],"kind":"Salzsee","group":"see","borders":["US"],"facts":["Der Große Salzsee in Utah ist der größte Salzsee der westlichen Hemisphäre; südöstlich von ihm liegt Salt Lake City.","Fische gibt es darin kaum, dafür Unmengen Salzkrebschen. Ein Bahndamm teilt den See – sein nördlicher Teil schimmert rötlich."]},{"id":"nicaraguasee","name":"Nicaraguasee","aliases":["Lago de Nicaragua","Lake Nicaragua","Cocibolca"],"kind":"See","group":"see","borders":["NI"],"facts":["Der Nicaraguasee ist der größte See Mittelamerikas; nur ein schmaler Landstreifen trennt ihn vom Pazifik, doch sein Abfluss, der Río San Juan, führt zur Karibik.","Bullenhaie können über den Río San Juan aus dem Meer bis in den See schwimmen; die Insel Ometepe im See besteht aus zwei Vulkanen."]},{"id":"titicaca","name":"Titicacasee","aliases":["Titikakasee","Titicaca","Lago Titicaca","Lake Titicaca"],"kind":"See","group":"see","borders":["PE","BO"],"facts":["Der Titicacasee liegt auf rund 3800 Metern in den Anden an der Grenze zwischen Peru und Bolivien und gilt als höchstgelegener schiffbarer See der Welt.","Das Volk der Uros lebt auf schwimmenden Inseln, die es aus Schilf aufschichtet.","Bolivien hat keinen Zugang zum Meer, unterhält aber eine Marine – sie übt unter anderem auf dem Titicacasee."]},{"id":"maracaibo","name":"Maracaibo-See","aliases":["Maracaibosee","Lago de Maracaibo","Lake Maracaibo"],"kind":"See","group":"see","borders":["VE"],"facts":["Der See im Nordwesten Venezuelas ist über eine Meerenge mit dem Meer verbunden. Der bekanntesten Erklärung nach erinnerten Pfahlbauten hier Seefahrer 1499 an Venedig – daher ‚Venezuela‘.","An 140 bis 160 Nächten im Jahr blitzt es über der Mündung des Catatumbo in den See – nirgends auf der Erde schlagen Blitze dichter ein."]},{"id":"ladoga","name":"Ladogasee","aliases":["Ladoga","Lake Ladoga"],"kind":"See","group":"see","borders":["RU"],"facts":["Der Ladogasee nordöstlich von Sankt Petersburg ist der größte See Europas; über die Newa fließt er in den Finnischen Meerbusen ab.","In ihm lebt die Ladoga-Ringelrobbe, eine der wenigen Robben der Welt, die im Süßwasser zu Hause sind."]},{"id":"onega","name":"Onegasee","aliases":["Onega","Lake Onega"],"kind":"See","group":"see","borders":["RU"],"facts":["Der Onegasee ist nach dem Ladogasee der zweitgrößte See Europas; er liegt im Nordwesten Russlands und ist über den Fluss Swir mit ihm verbunden.","Auf der Insel Kischi steht die Verklärungskirche von 1714 – ganz aus Holz und mit 22 Kuppeln; sie gehört zum UNESCO-Welterbe."]},{"id":"peipus","name":"Peipussee","aliases":["Peipsi","Peipsi järv","Lake Peipus"],"kind":"See","group":"see","borders":["EE","RU"],"facts":["Durch den Peipussee verläuft die Grenze zwischen Estland und Russland – er ist der größte grenzüberschreitende See Europas.","An seinem estnischen Westufer leben seit dem 18. Jahrhundert russische Altgläubige, deren Dörfer für ihren Zwiebelanbau bekannt sind."]},{"id":"saimaa","name":"Saimaa","aliases":["Saimaa-See","Saimaasee","Lake Saimaa"],"kind":"See","group":"see","borders":["FI"],"facts":["Der Saimaa im Südosten Finnlands ist der größte See des Landes – ein Labyrinth aus fast 14 000 Inseln, das der Saimaa-Kanal mit dem Finnischen Meerbusen verbindet.","Nur hier lebt die Saimaa-Ringelrobbe, eine der seltensten Robben der Welt."]},{"id":"vaenern","name":"Vänern","aliases":["Vänersee","Vänernsee","Lake Vänern","Vanern"],"kind":"See","group":"see","borders":["SE"],"facts":["Der Vänern im Südwesten Schwedens ist der größte See des Landes und sogar der ganzen Europäischen Union.","Über den Göta älv fließt er bei Göteborg ins Kattegat ab; zusammen mit dem Göta-Kanal bildet er einen Wasserweg quer durch Schweden bis zur Ostsee."]},{"id":"vaettern","name":"Vättern","aliases":["Vättersee","Lake Vättern","Vattern"],"kind":"See","group":"see","borders":["SE"],"facts":["Der lange, schmale Vättern liegt südöstlich des Vänern und ist der zweitgrößte See Schwedens.","Sein Wasser ist so sauber, dass viele Gemeinden rund um den See es als Trinkwasser nutzen – es braucht kaum Aufbereitung."]},{"id":"genfersee","name":"Genfer See","aliases":["Genfersee","Lac Léman","Léman","Lake Geneva","Lac de Genève"],"kind":"See","group":"see","borders":["CH","FR"],"facts":["Der Genfer See liegt zwischen der Schweiz und Frankreich; die Rhone fließt im Osten hinein und verlässt ihn in Genf wieder.","In Genf schießt der Jet d’Eau eine Wasserfontäne rund 140 Meter hoch – das Wahrzeichen der Stadt."]},{"id":"bodensee","name":"Bodensee","aliases":["Lake Constance","Schwäbisches Meer","Lac de Constance"],"kind":"See","group":"see","borders":["DE","AT","CH"],"facts":["Am Bodensee treffen Deutschland, Österreich und die Schweiz zusammen; der Rhein fließt als Alpenrhein hinein und verlässt ihn als Hochrhein.","Im Obersee, dem größten Teil des Sees, ist bis heute keine Staatsgrenze festgelegt – die drei Anrainer vertreten dazu unterschiedliche Auffassungen.","Im Jahr 1900 stieg bei Friedrichshafen über dem Bodensee das erste Zeppelin-Luftschiff auf."]},{"id":"gardasee","name":"Gardasee","aliases":["Lago di Garda","Lake Garda","Benaco"],"kind":"See","group":"see","borders":["IT"],"facts":["Der Gardasee am Südrand der Alpen ist der größte See Italiens; seine Ufer teilen sich die Lombardei, Venetien und das Trentino.","Bis nach dem Ersten Weltkrieg gehörte sein Nordufer mit Riva zu Österreich – die Grenze zu Italien verlief damals quer über den See."]},{"id":"comersee","name":"Comer See","aliases":["Comersee","Lago di Como","Lake Como","Lario"],"kind":"See","group":"see","borders":["IT"],"facts":["Der Comer See liegt in der Lombardei nahe der Schweizer Grenze und hat die Form eines umgedrehten Y.","Mit über 400 Metern ist er einer der tiefsten Seen Europas; sein Grund liegt mehr als 200 Meter unter dem Meeresspiegel."]},{"id":"balaton","name":"Plattensee","aliases":["Balaton","Lake Balaton"],"kind":"See","group":"see","borders":["HU"],"facts":["Der Plattensee im Westen Ungarns ist der größte See Mitteleuropas; die Ungarn nennen ihn Balaton.","Er ist im Schnitt nur gut drei Meter tief und wird im Sommer deshalb besonders warm – nicht umsonst heißt er auch ‚Ungarisches Meer‘."]},{"id":"mueritz","name":"Müritz","aliases":["Müritzsee","Mueritz"],"kind":"See","group":"see","borders":["DE"],"facts":["Die Müritz in Mecklenburg-Vorpommern ist der größte See, der vollständig in Deutschland liegt.","Ihr Name stammt vermutlich aus dem Slawischen und bedeutet ‚kleines Meer‘."]},{"id":"lochness","name":"Loch Ness","aliases":["Loch Nis"],"kind":"See","group":"see","borders":["GB"],"facts":["Loch Ness liegt im Great Glen, einer Grabenbruchzone quer durch die schottischen Highlands, und ist Teil des Kaledonischen Kanals.","Er enthält mehr Süßwasser als alle Seen Englands und von Wales zusammen."]},{"id":"loughneagh","name":"Lough Neagh","aliases":["Loch nEathach"],"kind":"See","group":"see","borders":["GB"],"facts":["Lough Neagh in Nordirland ist der größte See der Britischen Inseln; fünf der sechs nordirischen Grafschaften grenzen an ihn.","Der Sage nach riss der Riese Finn McCool hier ein Stück Erde heraus und schleuderte es ins Meer – daraus wurde die Isle of Man."]},{"id":"ijsselmeer","name":"IJsselmeer","aliases":["Zuiderzee","Lake IJssel"],"kind":"See","group":"see","borders":["NL"],"facts":["Das IJsselmeer war einst die Zuiderzee, eine Bucht der Nordsee: 1932 trennte der 32 Kilometer lange Abschlussdeich sie vom Meer, seither ist sie ein Süßwassersee.","Aus Teilen des Sees wurde Land gewonnen – der Flevopolder gilt als größte künstliche Insel der Welt."]},{"id":"skutarisee","name":"Skutarisee","aliases":["Shkodrasee","Skadarsee","Lake Skadar","Skadarsko jezero","Liqeni i Shkodrës"],"kind":"See","group":"see","borders":["ME","AL"],"facts":["Der Skutarisee ist der größte See Südeuropas; etwa zwei Drittel gehören zu Montenegro, ein Drittel zu Albanien.","Benannt ist er nach der albanischen Stadt Shkodra (Skutari); in seinen Sümpfen brüten Krauskopfpelikane."]},{"id":"totesmeer","name":"Totes Meer","aliases":["Dead Sea","Salzmeer"],"kind":"Salzsee","group":"see","borders":["JO","IL","PS"],"facts":["Die Ufer des Toten Meeres liegen über 430 Meter unter dem Meeresspiegel – die tiefste Landstelle der Erde. Und der Spiegel sinkt weiter, um rund einen Meter pro Jahr.","Mit über 30 Prozent Salz ist sein Wasser fast zehnmal so salzig wie das Meer; Menschen treiben darin wie Korken, Fische gibt es keine.","Es liegt zwischen Jordanien, Israel und dem Westjordanland; in Höhlen bei Qumran fand man die Schriftrollen vom Toten Meer, die ältesten bekannten Bibelhandschriften."]},{"id":"genezareth","name":"See Genezareth","aliases":["Genezareth","Galiläisches Meer","See von Tiberias","Kinneret","Sea of Galilee","Lake Tiberias"],"kind":"See","group":"see","borders":["IL"],"facts":["Der See Genezareth im Norden Israels liegt rund 210 Meter unter dem Meeresspiegel – er ist der tiefstgelegene Süßwassersee der Erde.","Der Jordan durchfließt ihn von Norden nach Süden. Nach dem Neuen Testament wirkte Jesus vor allem an seinen Ufern."]},{"id":"vansee","name":"Vansee","aliases":["Van-See","Van Gölü","Lake Van"],"kind":"Salzsee","group":"see","borders":["TR"],"facts":["Der Vansee in Ostanatolien ist der größte See der Türkei. Lavaströme des Vulkans Nemrut versperrten einst seinen Abfluss; seither verdunstet sein Wasser nur noch.","Sein Wasser ist salzig und stark alkalisch. Auf der Insel Akdamar steht eine armenische Kirche aus dem 10. Jahrhundert."]},{"id":"urmiasee","name":"Urmiasee","aliases":["Urmia-See","Orumiyeh-See","Lake Urmia"],"kind":"Salzsee","group":"see","borders":["IR"],"facts":["Der Urmiasee im Nordwesten Irans war einst der größte See Westasiens; durch Dürre, Staudämme und Wasserentnahme ist er seit den 1990er-Jahren zeitweise fast ausgetrocknet.","Salzliebende Algen und Bakterien färben sein Wasser zeitweise leuchtend rot."]},{"id":"sewansee","name":"Sewansee","aliases":["Sewan","Sevansee","Lake Sevan"],"kind":"See","group":"see","borders":["AM"],"facts":["Der Sewansee liegt auf rund 1900 Metern Höhe in Armenien und ist das größte Gewässer des Kaukasus.","Zu Sowjetzeiten sank sein Spiegel durch Wasserentnahme um rund 20 Meter – das Kloster Sewanawank, einst auf einer Insel, steht seither auf einer Halbinsel."]},{"id":"aralsee","name":"Aralsee","aliases":["Aral","Aral Sea"],"kind":"Salzsee","group":"see","borders":["KZ","UZ"],"facts":["Der Aralsee zwischen Kasachstan und Usbekistan war einst der viertgrößte See der Erde. Seit Amudarja und Syrdarja für Baumwollfelder angezapft wurden, schrumpfte er auf rund ein Zehntel.","Ein 2005 fertiggestellter Damm in Kasachstan hält das Wasser im nördlichen Teil zurück – dort ist der Spiegel wieder gestiegen, und Fische sind zurückgekehrt."]},{"id":"balchaschsee","name":"Balchaschsee","aliases":["Balchasch","Balkhash","Lake Balkhash"],"kind":"See","group":"see","borders":["KZ"],"facts":["Der Balchaschsee im Südosten Kasachstans wird vor allem vom Ili gespeist, der aus China kommt.","Er ist halb süß und halb salzig: Der Westteil enthält fast Süßwasser, der Ostteil salziges – verbunden sind beide nur durch eine schmale Meerenge."]},{"id":"issykkul","name":"Issyk-Kul","aliases":["Yssykköl","Issykkul","Issyk-Kul-See","Ysyk-Köl"],"kind":"See","group":"see","borders":["KG"],"facts":["Der Issyk-Kul liegt im Tianshan-Gebirge im Nordosten Kirgisistans; nach dem Titicacasee ist er der zweitgrößte Bergsee der Erde.","Sein Name bedeutet ‚heißer See‘: Trotz rund 1600 Metern Höhe friert er wegen seines leicht salzigen Wassers kaum je zu."]},{"id":"qinghaisee","name":"Qinghai-See","aliases":["Qinghaisee","Qinghai Hu","Kuku Nor","Koko Nor","Qinghai Lake"],"kind":"Salzsee","group":"see","borders":["CN"],"facts":["Der Qinghai-See am Nordostrand des Hochlands von Tibet ist der größte See Chinas; er liegt auf rund 3200 Metern Höhe und ist salzig.","Nach ihm ist die Provinz Qinghai benannt; der chinesische Name bedeutet ‚blaugrünes Meer‘, der mongolische, Kuku Nor, ‚blauer See‘."]},{"id":"tonlesap","name":"Tonle Sap","aliases":["Tonlé Sap","Tonle-Sap-See"],"kind":"See","group":"see","borders":["KH"],"facts":["Der Tonle Sap in Kambodscha ist der größte Süßwassersee Südostasiens; unweit seines Nordufers liegen die Tempel von Angkor.","In der Regenzeit drückt der Mekong so viel Wasser zurück, dass der Abfluss des Sees seine Richtung umkehrt – der See wächst dann auf mehr als das Fünffache."]},{"id":"tobasee","name":"Tobasee","aliases":["Toba-See","Danau Toba","Lake Toba"],"kind":"See","group":"see","borders":["ID"],"facts":["Der Tobasee im Norden Sumatras füllt die Caldera eines Supervulkans, dessen Ausbruch vor rund 74 000 Jahren der gewaltigste der letzten zwei Millionen Jahre war.","Die Insel Samosir in seiner Mitte ist mit rund 630 Quadratkilometern die größte Insel, die selbst auf einer Insel liegt."]},{"id":"biwasee","name":"Biwasee","aliases":["Biwa-See","Biwako","Biwa-ko","Lake Biwa"],"kind":"See","group":"see","borders":["JP"],"facts":["Der Biwasee nahe Kyoto ist der größte See Japans und versorgt Millionen Menschen in Kyoto und Osaka mit Trinkwasser.","Mit rund vier Millionen Jahren gehört er zu den ältesten Seen der Erde; seinen Namen hat er von der Biwa, einer Laute, deren Form er ähnelt."]},{"id":"tschadsee","name":"Tschadsee","aliases":["Lake Chad","Lac Tchad"],"kind":"See","group":"see","borders":["TD","CM","NE","NG"],"facts":["Im Tschadsee am Südrand der Sahara treffen die Grenzen von Tschad, Kamerun, Niger und Nigeria aufeinander; der Staat Tschad ist nach dem See benannt.","Der sehr flache See ist seit den 1960er-Jahren auf einen Bruchteil seiner früheren Fläche geschrumpft; seine Größe schwankt stark mit dem Regen."]},{"id":"turkanasee","name":"Turkanasee","aliases":["Rudolfsee","Lake Turkana","Lake Rudolf","Jadesee"],"kind":"Salzsee","group":"see","borders":["KE","ET"],"facts":["Der Turkanasee liegt im Norden Kenias, seine Nordspitze reicht nach Äthiopien. Europäer nannten ihn früher Rudolfsee – nach Österreichs Kronprinz Rudolf.","Er ist der größte dauerhafte Wüstensee und der größte alkalische See der Erde; an seinen Ufern fand man bedeutende Fossilien früher Menschen."]},{"id":"tanasee","name":"Tanasee","aliases":["Tana-See","Lake Tana"],"kind":"See","group":"see","borders":["ET"],"facts":["Der Tanasee im Hochland von Äthiopien ist der größte See des Landes; aus ihm fließt der Blaue Nil, der den größten Teil des Nilwassers liefert.","Auf seinen Inseln stehen jahrhundertealte Klöster der äthiopisch-orthodoxen Kirche mit kostbaren Wandmalereien und Handschriften."]},{"id":"kiwusee","name":"Kiwusee","aliases":["Kivusee","Lake Kivu","Lac Kivu"],"kind":"See","group":"see","borders":["CD","RW"],"facts":["Der Kiwusee liegt im Zentralafrikanischen Graben an der Grenze zwischen der Demokratischen Republik Kongo und Ruanda; er entwässert über den Ruzizi in den Tanganjikasee.","In seinem Tiefenwasser sind riesige Mengen Methan und Kohlendioxid gelöst; Ruanda fördert das Methan und erzeugt daraus Strom."]},{"id":"albertsee","name":"Albertsee","aliases":["Lake Albert","Lac Albert","Mobutu-Sese-Seko-See"],"kind":"See","group":"see","borders":["UG","CD"],"facts":["Der Albertsee liegt im Zentralafrikanischen Graben an der Grenze zwischen Uganda und der Demokratischen Republik Kongo; der Nil durchfließt seinen Nordteil.","Der Brite Samuel Baker benannte ihn 1864 nach Prinz Albert, dem verstorbenen Ehemann von Königin Victoria."]},{"id":"karibasee","name":"Karibasee","aliases":["Kariba-Stausee","Lake Kariba"],"kind":"Stausee","group":"see","borders":["ZM","ZW"],"facts":["Der Karibasee entstand ab 1958 durch den Kariba-Damm am Sambesi; er liegt an der Grenze zwischen Sambia und Simbabwe.","Gemessen am Volumen ist er der größte Stausee der Welt. Als das Wasser stieg, retteten Wildhüter bei der ‚Operation Noah‘ Tausende Tiere."]},{"id":"voltasee","name":"Voltasee","aliases":["Volta-Stausee","Lake Volta"],"kind":"Stausee","group":"see","borders":["GH"],"facts":["Der Voltasee in Ghana ist der flächenmäßig größte Stausee der Welt; er entstand in den 1960er-Jahren durch den Akosombo-Damm am Volta.","Er bedeckt rund 3,6 Prozent der Fläche Ghanas; das Wasserkraftwerk am Damm liefert einen großen Teil des Stroms im Land."]},{"id":"nassersee","name":"Nassersee","aliases":["Nasser-Stausee","Lake Nasser","Nubiasee"],"kind":"Stausee","group":"see","borders":["EG","SD"],"facts":["Der Nassersee entstand durch den 1970 fertiggestellten Assuan-Staudamm und trägt den Namen des früheren ägyptischen Präsidenten Nasser; sein Südteil im Sudan heißt Nubiasee.","Um sie vor dem steigenden Wasser zu retten, wurden die Tempel von Abu Simbel in Blöcke zersägt und 65 Meter höher wieder aufgebaut."]},{"id":"eyresee","name":"Eyresee","aliases":["Lake Eyre","Kati Thanda","Kati Thanda–Lake Eyre"],"kind":"Salzsee","group":"see","borders":["AU"],"facts":["Der Eyresee in der Wüste Südaustraliens liegt rund 15 Meter unter dem Meeresspiegel – der tiefste Punkt Australiens; offiziell heißt er Kati Thanda–Lake Eyre.","Meist ist er eine trockene Salzfläche; nur selten füllt er sich ganz mit Wasser – dann kommen Pelikane zu Zehntausenden."]}];
